#include <unordered_map>
#include <array>
#include <map>
#include <iomanip>

using namespace std;

typedef long long int llint;

int main(void){
    int n; cin >> n;
    static int aizu[200300] = {0};
    for(int i = 0; i < n; i++){
        int a, b; cin >> a >> b;
        aizu[a + b]++;
    }
    for(int i = 0; i < 200279; i++){
        aizu[i + 1] += aizu[i] / 2;
        aizu[i] %= 2;
        if(aizu[i] == 1) cout << i << " 0\n";
    }
    return 0;
}

